const { topic_id, topic_name, count } = $input.item.json.body;

const prompt = `Analyze this topic and generate quiz cards: "${topic_name}"

First, determine if this is anime/manga related (Japanese animation, manga series, light novels, anime characters).

Then generate ${count || 30} quiz cards.

For ANIME/MANGA topics:
- Provide the MyAnimeList search query for each character
- Use the character's full name as it appears on MyAnimeList

For NON-ANIME topics (K-pop, movies, TV shows, celebrities, sports, etc.):
- Provide the Wikipedia slug
- Replace spaces with underscores
- Add disambiguation in parentheses if needed

Return ONLY valid JSON:
{
  "is_anime": true/false,
  "cards": [
    {
      "correct_answer": "Character/Person Name",
      "search_query": "search term for MAL or Wikipedia slug"
    }
  ]
}

Examples:
- "Characters of Jujutsu Kaisen" → is_anime: true, search_query: "Yuji Itadori"
- "Members of BTS" → is_anime: false, search_query: "Kim_Namjoon"
- "Characters of Breaking Bad" → is_anime: false, search_query: "Walter_White_(Breaking_Bad)"`;

return { prompt, topic_id, topic_name, count: count || 30 };

const claudeResponse = $input.first().json.content[0].text;
const { topic_id, topic_name } = $node['Build Claude Prompt'].json;

// Extract JSON from Claude response
const jsonMatch = claudeResponse.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  throw new Error('No JSON found in Claude response');
}

const parsed = JSON.parse(jsonMatch[0]);
const isAnime = parsed.is_anime === true;

// Output each card as separate item
return parsed.cards.map((card, index) => ({
  json: {
    topic_id,
    topic_name,
    card_id: `${topic_id}_${String(index + 1).padStart(3, '0')}`,
    correct_answer: card.correct_answer,
    search_query: card.search_query,
    is_anime: isAnime
  }
}));

const jikanResponse = $input.item.json;

// Get the current item data that was passed through the loop
const currentItem = $('Loop Over Items').item.json;

let imageUrl = null;

// Extract image from Jikan response
if (jikanResponse && 
    jikanResponse.data && 
    Array.isArray(jikanResponse.data) && 
    jikanResponse.data.length > 0) {

  const character = jikanResponse.data[0];

  // Jikan provides images in this structure
  if (character.images) {
    // Prefer JPG, then WebP
    if (character.images.jpg && character.images.jpg.image_url) {
      imageUrl = character.images.jpg.image_url;
    } else if (character.images.webp && character.images.webp.image_url) {
      imageUrl = character.images.webp.image_url;
    }
  }
}

return {
  topic_id: currentItem.topic_id,
  topic_name: currentItem.topic_name,
  card_id: currentItem.card_id,
  correct_answer: currentItem.correct_answer,
  imageUrl: imageUrl,
  source: 'jikan'
};

const wikiResponse = $input.item.json;
const allCards = $('Parse Claude Response').all();
const cardData = allCards[$itemIndex].json;

let imageUrl = null;

// Check if Wikipedia API returned valid data with pageimages
if (wikiResponse && 
    wikiResponse.query && 
    wikiResponse.query.pages &&
    Array.isArray(wikiResponse.query.pages) &&
    wikiResponse.query.pages.length > 0) {

  const page = wikiResponse.query.pages[0];

  // pageimages API returns the main infobox image directly
  if (page && !page.missing && page.original && page.original.source) {
    imageUrl = page.original.source;
  }
}

return {
  topic_id: cardData.topic_id,
  topic_name: cardData.topic_name,
  card_id: cardData.card_id,
  correct_answer: cardData.correct_answer,
  search_query: cardData.search_query,
  imageUrl: imageUrl,
  hasImage: imageUrl !== null,
  source: 'wikipedia'
};

const wikiResponse = $input.item.json;
const fallbackItems = $('Need Fallback?').all();
const prevData = fallbackItems[$itemIndex].json;

let imageFilename = null;

if (wikiResponse && 
    wikiResponse.query && 
    wikiResponse.query.pages &&
    Array.isArray(wikiResponse.query.pages) &&
    wikiResponse.query.pages.length > 0) {

  const page = wikiResponse.query.pages[0];

  if (page && !page.missing && page.images && Array.isArray(page.images) && page.images.length > 0) {
    // Filter out common Wikipedia UI images
    const excludePatterns = [
      'ambox', 'icon', 'logo', 'commons-logo', 'wikidata', 'wikiquote',
      'edit-', 'lock-', 'question', 'info', 'disambig', 'folder',
      'crystal', 'nuvola', 'gnome', 'tango', 'farm-fresh', 'ooui',
      'red_pencil', 'increase', 'decrease', 'steady', 'symbol_'
    ];

    const validExtensions = ['.jpg', '.jpeg', '.png', '.webp'];

    // Find first valid image
    const bestImage = page.images.find(img => {
      if (!img.title) return false;
      const titleLower = img.title.toLowerCase();
      if (excludePatterns.some(p => titleLower.includes(p))) return false;
      return validExtensions.some(ext => titleLower.endsWith(ext));
    });

    if (bestImage) {
      imageFilename = bestImage.title;
    }
  }
}

return {
  ...prevData,
  imageFilename,
  hasFilename: imageFilename !== null
};

const imageInfoResponse = $input.item.json;
const filenameItems = $('Has Filename?').all();
const prevData = filenameItems[$itemIndex].json;

let imageUrl = null;

if (imageInfoResponse && 
    imageInfoResponse.query && 
    imageInfoResponse.query.pages &&
    Array.isArray(imageInfoResponse.query.pages) &&
    imageInfoResponse.query.pages.length > 0) {

  const page = imageInfoResponse.query.pages[0];

  if (page && page.imageinfo && page.imageinfo.length > 0) {
    imageUrl = page.imageinfo[0].url;
  }
}

return {
  topic_id: prevData.topic_id,
  topic_name: prevData.topic_name,
  card_id: prevData.card_id,
  correct_answer: prevData.correct_answer,
  imageUrl: imageUrl,
  source: 'wikipedia-fallback'
};

// Pass through items that already have an image (no fallback needed)
const data = $input.item.json;
return {
  topic_id: data.topic_id,
  topic_name: data.topic_name,
  card_id: data.card_id,
  correct_answer: data.correct_answer,
  imageUrl: data.imageUrl,
  source: 'wikipedia-direct'
};

// Pass through items with no image found
const data = $input.item.json;
return {
  topic_id: data.topic_id,
  topic_name: data.topic_name,
  card_id: data.card_id,
  correct_answer: data.correct_answer,
  imageUrl: null,
  source: 'wikipedia-no-image'
};

